runm bvh bvh_parse_max_tri      src/bvh_core.h "s/kMaxTri4 = 0x3ffffff/kMaxTri4 = 0x7ffffff/"
runm bvh bvh_parse_max_node     src/bvh_core.h "s/kMaxNodes = 0xfffffff/kMaxNodes = 0x1fffffff/"
runm bvh bvh_parse_max_tri_cmp  src/bvh_core.h "s/s0 \/ sizeof(Tri4) > kMaxTri4/false/"
runm bvh bvh_parse_max_node_cmp src/bvh_core.h "s/s1 \/ sizeof(Node) > kMaxNodes/false/"
runm bvh bvh_parse_tri_follow   src/bvh_core.h "s/p0 ? p0 : hdr_addr + kHeaderSize;/p0;/"
runm bvh bvh_parse_node_follow  src/bvh_core.h "s/p1 ? p1 : hdr_addr + kHeaderSize + s0;/p1;/"
runm bvh bvh_parse_follow_off   src/bvh_core.h "s/hdr_addr + kHeaderSize + s0;/hdr_addr + kHeaderSize;/"
runm bvh bvh_parse_wrap_tri     src/bvh_core.h "s/tp + s0 < tp || //"
runm bvh bvh_parse_wrap_node    src/bvh_core.h "s/np + s1 < np || //"
