runm bvh bvh_parse_nullpage_nd  src/bvh_core.h "s/ || np < 0x10000//"
runm bvh bvh_parse_root         src/bvh_core.h "s/tree->root = static_cast<int32_t>(root);/tree->root = 0;/"
