runm bvh bvh_parse_tri_sz_off   src/bvh_core.h "s/memcpy(\&s0, hdr + 0x08, 8);/memcpy(\&s0, hdr + 0x10, 8);/"
runm bvh bvh_header_size        src/bvh_core.h "s/kHeaderSize = 0x50;/kHeaderSize = 0x48;/"
# -- ray
runm bvh bvh_ray_finite         src/bvh_core.h "s/ok = ok \&\& isfinite(org\[k\]) \&\& isfinite(dir\[k\]);//"
runm bvh bvh_ray_finite_org     src/bvh_core.h "s/ok = ok \&\& isfinite(org\[k\]) \&\& isfinite(dir\[k\]);/ok = ok \&\& isfinite(dir[k]);/"
