runm bvh bvh_ray_range_order    src/bvh_core.h "s/ \&\& tmax_ >= tmin_;/;/"
# -- box and triangle
runm bvh bvh_box_swap           src/bvh_core.h "s/    if (a > z) {/    if (false) {/"
