runm bvh bvh_box_never_miss     src/bvh_core.h "s/return t0 <= t1 ? t0 : -1.0f;/return t0;/"
runm bvh bvh_box_tmax           src/bvh_core.h "s/float t0 = r.tmin, t1 = tmax;/float t0 = r.tmin, t1 = r.tmax;/"
runm bvh bvh_tri_u_lo           src/bvh_core.h "s/if (u < 0.0f) return false;/if (false) return false;/"
