runm bvh bvh_tri_v1_sign        src/bvh_core.h "s/const float a\[3\] = {-q.e1\[0\]\[l\], -q.e1\[1\]\[l\], -q.e1\[2\]\[l\]};/const float a[3] = {q.e1[0][l], q.e1[1][l], q.e1[2][l]};/"
# -- traversal
runm bvh bvh_trace_ray_ok       src/bvh_core.h "s/if (!r.ok) return false;/if (false) return false;/"
runm bvh bvh_trace_budget       src/bvh_core.h "s/2ull \* tree.nnodes + 2;/2ull * tree.nnodes + 1000000;/"
runm bvh bvh_trace_budget_tight src/bvh_core.h "s/2ull \* tree.nnodes + 2;/tree.nnodes;/"
runm bvh bvh_trace_budget_cmp   src/bvh_core.h "s/if (++pops > max_pops) return false;/if (++pops >= max_pops) return false;/"
runm bvh bvh_trace_stack_size   src/bvh_core.h "s/kStackSize = 128;/kStackSize = 64;/"
