runm bvh bvh_trace_stack_off    src/bvh_core.h "s/if (sp + 2 > kStackSize) return false;/if (sp + 1 > kStackSize) return false;/"
runm bvh bvh_trace_node_bound   src/bvh_core.h "s/if (ni >= tree.nnodes) return false;/if (ni > tree.nnodes) return false;/"
