runm bvh bvh_trace_empty_child1 src/bvh_core.h "s/n.child\[1\] == INT32_MIN ? -1.0f : /\/\*x\*\/ /"
runm bvh bvh_trace_empty_lane   src/bvh_core.h "s/if (q.id0\[l\] == -1) continue;/\/\*x\*\//"
runm bvh bvh_trace_leaf_shift   src/bvh_core.h "s/\& 0x7fffffffu) >> 5, cnt/\& 0x7fffffffu) >> 4, cnt/"
runm bvh bvh_trace_leaf_count   src/bvh_core.h "s/cnt = static_cast<uint32_t>(id) \& 31u;/cnt = static_cast<uint32_t>(id) \& 15u;/"
runm bvh bvh_trace_inner_shift  src/bvh_core.h "s/static_cast<uint32_t>(id) >> 3;/static_cast<uint32_t>(id) >> 2;/"
runm bvh bvh_trace_entry_prune  src/bvh_core.h "s/if (entry\[sp\] > best) continue;/\/\*x\*\//"
runm bvh bvh_trace_any_stops    src/bvh_core.h "s/if (any) goto done;/\/\*x\*\//"
runm bvh bvh_trace_near_first   src/bvh_core.h "s/(e1 < 0 || e0 <= e1)/(e1 < 0 || e0 >= e1)/"
runm bvh bvh_trace_best_closer  src/bvh_core.h "s/        best = t;/        best = r.tmax;/"
runm bvh bvh_trace_tmax         src/bvh_core.h "s/float best = r.tmax;/float best = 1e30f;/"
runm bvh bvh_trace_root         src/bvh_core.h "s/stack\[sp\] = static_cast<uint32_t>(tree.root);/stack[sp] = 0;/"
runm bvh bvh_trace_id1          src/bvh_core.h "s/out->id1 = bq->id1\[bl\];/out->id1 = bq->id0[bl];/"
runm bvh bvh_trace_id0          src/bvh_core.h "s/out->id0 = bq->id0\[bl\];/out->id0 = bq->id1[bl];/"
runm bvh bvh_trace_u            src/bvh_core.h "s/out->u = bu;/out->u = bv;/"
runm bvh bvh_trace_v            src/bvh_core.h "s/out->v = bv;/out->v = bu;/"
runm bvh bvh_trace_normal       src/bvh_core.h "s/out->n\[k\] = len > 0 ? g\[k\] \/ len : 0.0f;/out->n[k] = g[k];/"
runm bvh bvh_trace_normal_zero  src/bvh_core.h "s/out->n\[k\] = len > 0 ? g\[k\] \/ len : 0.0f;/out->n[k] = g[k] \/ len;/"
runm bvh bvh_trace_hit_t        src/bvh_core.h "s/out->t = best;/out->t = r.tmax;/"
# Not listed, because the rule is redundant by construction and no test can tell it apart: the `det == 0 || !isfinite(det)` guard in
# TriHit (IEEE division already ends in a miss), `u > 1` (u + v > 1 with v >= 0), the NaN-range compare (tmax >= tmin is false for NaN),
# the page probe's last byte (every page of the range is probed), the `p == 0` / `p < lo` tests in TreeOf (off wraps), and the
# expected-vaddr argument of InstallImportHook (the pre-check reads the same word first).